import uuid
from datetime import date

from pydantic import BaseModel, ConfigDict, EmailStr, Field, HttpUrl


class Profile(BaseModel):
    """Profile data sent by the client; the id is generated by the server."""

    full_name: str = Field(min_length=1)
    headline: str = Field(min_length=1)

    email: EmailStr
    phone: str | None = None
    location: str | None = None
    about: str | None = None

    linkedin_url: HttpUrl | None = None
    github_url: HttpUrl | None = None
    portfolio_url: HttpUrl | None = None

    birth_date: date | None = None


class ProfileRead(Profile):
    """Profile returned by the API, including its id."""

    # Allows building from ORM objects: ProfileRead.model_validate(profile_orm).
    model_config = ConfigDict(from_attributes=True)

    id: uuid.UUID
